WITH upsert AS (
        UPDATE icam01_data_info
           SET icam01_info_nm           = #{p.infoName}
             , icam01_tr_nm             = #{p.trName}
             , icam01_ics_class_tree_id = #{p.icsClassTreeId}
             , icam01_note              = #{p.note}
         WHERE icam01_info_cd = #{p.infoCode}
           AND icam01_tr_cd   = #{p.trCode}
     RETURNING *
)
    INSERT
      INTO icam01_data_info
         ( icam01_data_info_id
         , icam01_info_cd
         , icam01_info_nm
         , icam01_tr_cd
         , icam01_tr_nm
         , icam01_ics_class_tree_id
         , icam01_note
         )
    SELECT f_create_seq()
         , #{p.infoCode}
         , #{p.infoName}
         , #{p.trCode}
         , #{p.trName}
         , #{p.icsClassTreeId}
         , #{p.note}
     WHERE NOT EXISTS ( SELECT * FROM upsert )
